			skb = skb_copy(skb, GFP_ATOMIC);

		skb->dev = slave;
		skb->protocol = eth_type_trans(skb, slave);
		skb->ip_summed = CHECKSUM_UNNECESSARY;
		bond->stats.tx_packets++;
